mapper.delete:
delete from CHB_AST_VAL_SUB c
to_char(c.VAL_DATE,'yyyy-MM-dd') = #{valDate,jdbcType=VARCHAR}
and c.STATUS = #{status,jdbcType=VARCHAR}
and c.SEND_STATUS = #{sendStatus,jdbcType=VARCHAR}
and c.regist_seqno in (select d.regist_seqno from CHB_AST_VAL_SUB d left join chb_asset_info_sub csb on csb.ASSET_CODE=d.ASSET_CODE LEFT JOIN FIN_PRODUCT F ON csb.ASSET_CODE=F.FINPROD_MARKET_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD PDD ON csb.ASSET_CODE = PDD.TRADE_ID LEFT JOIN (SELECT PORTFOLIO_ID,FINPROD_ID FROM TRD_FIN_PRODUCT_DEAL_TOTAL WHERE PORTFOLIO_ID IS NOT NULL GROUP BY PORTFOLIO_ID,FINPROD_ID) DEAL ON DEAL.FINPROD_ID = csb.ASSET_CODE LEFT JOIN ( SELECT D.BUSINESS_ID,D.BELONG_INSTITUTION_CODE,D.DATA_TYPE FROM DATA_AUTH_NOTIFY_INST D WHERE D.MODEL_TYPE = '02' GROUP BY D.BUSINESS_ID,D.BELONG_INSTITUTION_CODE,D.DATA_TYPE ) DA ON ((DA.BUSINESS_ID = F.FINPROD_ID OR DA.BUSINESS_ID=DEAL.PORTFOLIO_ID) and DATA_TYPE != 'PTL01') or (DA.BUSINESS_ID = PDD.PORTFOLIO_ID and DATA_TYPE = 'PTL01') LEFT JOIN CHB_ASSET_SUB_STATUS CS ON csb.REGIST_SEQNO=CS.REGIST_SEQNO AND CS.ASSET_TYPE='01' where ( (CS.INSTITUTION_CODE =#{InstitutionCode,jdbcType=VARCHAR} and F.TRADE_MARKET IS NOT NULL) or (F.TRADE_MARKET IS NULL and DA.BELONG_INSTITUTION_CODE=#{InstitutionCode,jdbcType=VARCHAR} and CS.INSTITUTION_CODE=#{InstitutionCode,jdbcType=VARCHAR} )) )
